head.script:
// displayFormatFunc 호출 기록 (gridView 생성 시점에 호출되므로 onpageload 에서 출력)
scwin.callLog = [];

// displayFormatFunc 로 지정한 사용자 함수
scwin.fn_displayFormat = function (calendarValueType) {
    let ret = "yyyy/MM/dd";
    scwin.callLog.push("displayFormatFunc 호출 : " + calendarValueType + " -> " + ret);
    return ret;
};

scwin.onpageload = function () {
    for (let i = 0; i < scwin.callLog.length; i++) {
        scwin.setReturnValue(scwin.callLog[i]);
    }
    let td = grd_data.render.querySelector("td[data-col_id='cal']");
    scwin.setReturnValue("호출 횟수 : " + scwin.callLog.length
        + " / 셀 표시값 : " + (td ? td.textContent : "")
        + " / 기대 표시값 : 2026/10/01");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
